func (s *ReadAtMostSuite) TestReadAtMostScratch(c *check.C) {
	// limit bigger than content: full read, no error
	data, err := ReadAtMost(bytes.NewReader([]byte("hello")), 10)
	c.Assert(err, check.IsNil)
	c.Assert(string(data), check.Equals, "hello")

	// limit smaller than content: partial data and ErrLimitReached
	data, err = ReadAtMost(bytes.NewReader([]byte("hello world")), 5)
	c.Assert(trace.Unwrap(err), check.FitsTypeOf, ErrLimitReached)
	c.Assert(err, check.ErrorMatches, ".*limit of response size exceeded.*")
	c.Assert(string(data), check.Equals, "hello")

	// underlying reader error is propagated
	failing := &errorReader{err: errors.New("boom")}
	data, err = ReadAtMost(failing, 10)
	c.Assert(err, check.ErrorMatches, "boom")
	c.Assert(len(data), check.Equals, 0)

	// empty reader with a positive limit
	data, err = ReadAtMost(bytes.NewReader(nil), 10)
	c.Assert(err, check.IsNil)
	c.Assert(len(data), check.Equals, 0)
}

type errorReader struct {
	err error
}

func (r *errorReader) Read(p []byte) (int, error) {
	return 0, r.err
}
